package com.aetnox.cooking.ui.utilimport android.content.ComponentNameimport android.content.Contextimport android.content.pm.PackageManagerimport androidx.compose.runtime.mutableStateOfenum class AppIconVariant(    private val ruLabel: String,    private val enLabel: String,    val aliasName: String) {    DEFAULT("🎨 Полноцветная фирменная", "🎨 Full Color Brand", "com.aetnox.cooking.MainActivityAliasDefault"),    NEON("✨ Неоновая кулинария", "✨ Neon Culinary", "com.aetnox.cooking.MainActivityAliasNeon"),    NIGHT_CHEF("🌙 Ночной Шеф", "🌙 Night Chef", "com.aetnox.cooking.MainActivityAliasNightChef"),    NOTHING("⚫ Nothing (Dot Style)", "⚫ Nothing (Dot Style)", "com.aetnox.cooking.MainActivityAliasNothing");    val label: String        get() = AppLocaleManager.tr(ruLabel, enLabel)}object AppIconManager {    private const val PREFS_NAME = "cooking_prefs"    private const val KEY_APP_ICON = "app_icon_variant"    val currentIconVariant = mutableStateOf(AppIconVariant.DEFAULT)    fun init(context: Context) {        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)        val defaultVariant = if (com.aetnox.cooking.data.remote.DeviceUtils.isNothingDevice()) AppIconVariant.NOTHING else AppIconVariant.DEFAULT        val name = prefs.getString(KEY_APP_ICON, defaultVariant.name)        val variant = runCatching { AppIconVariant.valueOf(name!!) }.getOrDefault(defaultVariant)        currentIconVariant.value = variant        syncAppIconState(context, variant)    }    fun setAppIcon(context: Context, variant: AppIconVariant) {        syncAppIconState(context, variant)        context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)            .edit()            .putString(KEY_APP_ICON, variant.name)            .apply()        currentIconVariant.value = variant    }    private fun syncAppIconState(context: Context, activeVariant: AppIconVariant) {        val pm = context.packageManager        // Ensure main target activity is enabled        runCatching {            val mainComp = ComponentName(context.packageName, "com.aetnox.cooking.MainActivity")            pm.setComponentEnabledSetting(                mainComp,                PackageManager.COMPONENT_ENABLED_STATE_ENABLED,                PackageManager.DONT_KILL_APP            )        }        // Toggle launcher alias components        AppIconVariant.entries.forEach { item ->            val compName = ComponentName(context.packageName, item.aliasName)            val state = if (item == activeVariant) {                PackageManager.COMPONENT_ENABLED_STATE_ENABLED            } else {                PackageManager.COMPONENT_ENABLED_STATE_DISABLED            }            try {                pm.setComponentEnabledSetting(                    compName,                    state,                    PackageManager.DONT_KILL_APP                )            } catch (_: Exception) {                // Safe fallback            }        }    }}